/// <summary>
/// designed from AVA
/// </summary>
public void buildQuery()
{
    QueryBuildDataSource        searchTableQBDS      = KCS_KBVSearchTable_ds.query().dataSourceTable(tableNum(KCS_KBVSearchTable));
    QueryBuildDataSource        buildingProjectQBDS  = KCS_KBVBuildingProjectTable_ds.query().dataSourceTable(tableNum(KCS_KBVBuildingProjectTable));

    searchTableQBDS.clearRanges();
    buildingProjectQBDS.clearRanges();

 //  searchTableQBDS.

    QueryBuildRange             searchTableRecIdRange = SysQuery::findOrCreateRange(searchTableQBDS,fieldNum(KCS_KBVSearchTable,RecId));
    QueryBuildRange             buildingProjectRange  = SysQuery::findOrCreateRange(buildingProjectQBDS,fieldNum(KCS_KBVBuildingProjectTable,RecId));


    MapEnumerator           rangeEnumerator = filterMap.getEnumerator();

    while (rangeEnumerator.moveNext())
    {
        switch (rangeEnumerator.currentKey())
        {
            case tableNum(KCS_KBVSearchTable)           : 
                searchTableRecIdRange.value(rangeEnumerator.currentValue());
                break;
            default :
                buildingProjectRange.value(rangeEnumerator.currentValue());
                break;
        }
    }


}

/// <summary>
///  designed from AVA
/// </summary>

void buildQueryRanges()
{

    void rangeSearchValue(tableId _tableNum, 
                          fieldId _fieldNum,
                          AVASearchString   _search, 
                          AVASqlOperator _sqlOperator,
                          boolean _or = false,
                          AVASearchString _search2 = '',
                          AVASqlOperator _sqlOperator2 = AVASqlOperator::First,
                          AVAKBVSearchPersonOrContact _isRequestOrIoR = AVAKBVSearchPersonOrContact::None,                     
                          boolean _setOpenBracket = false,                      
                          boolean _setCloseBracket = false,                     
                          boolean _setSecondOpenBracket = false,                
                          boolean _setSecondCloseBracket = false)              
    {
        anytype                 keyValue = _tableNum;
        anyType                 value;
        anyType                 value2;
        str                     fieldName;
        ;

        fieldName   = strfmt('%1.%2', tableid2name(_tableNum), fieldid2name(_tableNum, _fieldNum));
        value       = strfmt('(%1 %2)', fieldName,  KCS_KBVSearchTable::getSearchFieldValue(_search, _sqlOperator, new DictField(_tableNum, _fieldNum).baseType()));
        value2      = strfmt('(%1 %2)', fieldName,  KCS_KBVSearchTable::getSearchFieldValue(_search2, _sqlOperator2, new DictField(_tableNum, _fieldNum).baseType()));                

        if (_setOpenBracket)
        {
            value = strfmt('(%1', value);
        }

        if (_setCloseBracket)
        {
            value = strfmt('%1)', value);
        }

        if (_setSecondOpenBracket)
        {
            value = strfmt('(%1', value);
        }

        if (_setSecondCloseBracket)
        {
            value = strfmt('%1)', value);
        }

        if (filterMap.exists(keyValue))
        {
            if (filterMap.lookup(keyValue) != value)
            {
                if (!_or)
                {
                    if (_isRequestOrIoR)
                    {
                        filterMap.insert(keyValue, strfmt('%1 || %2' , filterMap.lookup(keyValue), value));
                    }
                    else
                    {
                        filterMap.insert(keyValue, strfmt('%1 && %2' , filterMap.lookup(keyValue), value));
                    }
                }
                else
                {
                    filterMap.insert(keyValue, strfmt('%1 && (%2 && %3)' , filterMap.lookup(keyValue), value, value2));
                }
            }
        }
        else
        {
            if (!_or)
            {
                filterMap.insert(keyValue, value);
            }
            else
            {
                filterMap.insert(keyValue, '(' + value + '&&' + value2 + ')');
            }
        }
    }

    ;

    filterMap = new Map(Types::Integer, Types::String);

    if (buildingProjectId)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVBuildingProjectID), buildingProjectId , operatorBuildingProjectId);
    }

    if(subject && subject2)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVSubject), subject, operatorSubject, true, subject2, operatorSubject2);
    }
    else if(subject)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVSubject), subject, operatorSubject);
    }
    else if(subject2)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVSubject), subject2, operatorSubject2);
    }


    if (city)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, AddressCity), city, operatorCity);
    }

    if (country)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, AddressCountryRegionId), country, operatorCountry);
    }

    if (tenderFirstQty)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVTenderFirstPositionQty), tenderFirstQty, operatorTenderFirstQty);
    }

    if(tenderFirst)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVTenderFirstPosition), KCS_KBVSearchTable::convertLVNumber(tenderFirst), operatorTenderFirst);
    }

    if (partyName)
    {
        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchTableId),
        int2str(tablenum(KCS_KBVRequestTable)),
        AVASqlOperator::Is,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::None,
        true,
        false);

        rangeSearchValue(tableNum(KCS_KBVSearchTable), fieldNum(KCS_KBVSearchTable, SearchFieldId), int2str(fieldnum(KCS_KBVRequestTable, DirPartyId)), AVASqlOperator::Is);

        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchValue),
        partyName,
        operatorParty,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::None,
        false,
        true);

        rangeSearchValue(tableNum(KCS_KBVSearchTable), 
        fieldNum(KCS_KBVSearchTable, SearchTableId), 
        int2str(tablenum(KCS_KBVInquirerOfTheRequest)), 
        AVASqlOperator::Is,
        false, 
        '', 
        AVASqlOperator::First, 
        AVAKBVSearchPersonOrContact::PartyId, 
        true, 
        false);

        rangeSearchValue(tableNum(KCS_KBVSearchTable), 
        fieldNum(KCS_KBVSearchTable, SearchFieldId), 
        int2str(fieldnum(KCS_KBVInquirerOfTheRequest, DirPartyId)), 
        AVASqlOperator::Is);

        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchValue),
        partyName,
        operatorParty,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::None,
        false,
        true);
    }

    if (contactName)
    {
        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchValue),
        contactName,
        operatorContact,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::None,
        true,
        false);

        // Einschränkung
        rangeSearchValue(tableNum(KCS_KBVSearchTable), 
        fieldNum(KCS_KBVSearchTable, SearchTableId),
        int2str(tablenum(KCS_KBVInquirerOfTheRequest)), 
        AVASqlOperator::Is);

        rangeSearchValue(tableNum(KCS_KBVSearchTable), 
        fieldNum(KCS_KBVSearchTable, SearchFieldId), 
        int2str(fieldnum(KCS_KBVInquirerOfTheRequest, ContactPersonId)),
        AVASqlOperator::Is, 
        false, 
        '', 
        AVASqlOperator::First, 
        AVAKBVSearchPersonOrContact::None, 
        false, 
        true);

        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchValue),
        contactName,
        operatorContact,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::PartyId,
        true,
        false);

        rangeSearchValue(tableNum(KCS_KBVSearchTable), 
        fieldNum(KCS_KBVSearchTable, SearchTableId), 
        int2str(tablenum(KCS_KBVRequestTable)), 
        AVASqlOperator::Is);

        rangeSearchValue(tableNum(KCS_KBVSearchTable),
        fieldNum(KCS_KBVSearchTable, SearchFieldId),
        int2str(fieldnum(KCS_KBVRequestTable, ContactPersonId)),
        AVASqlOperator::Is,
        false,
        '',
        AVASqlOperator::First,
        AVAKBVSearchPersonOrContact::None,
        false,
        true);
    }

    if (tender)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVTenderID), tender, operatorTender);
    }

    if (placingNumber)
    {
        rangeSearchValue(tableNum(KCS_KBVBuildingProjectTable), fieldNum(KCS_KBVBuildingProjectTable, KCS_KBVPlacingNumber), placingNumber, operatorPlacingNumber);
    }

}

